import{_ as a,W as i,s as l,u as d,ah as r,I as n,w as s,Z as o,A as p}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const k=JSON.parse('{"title":"如何在家中使用 SSH 和 SFTP 协议 | LCTT x X-CMD","titleTemplate":false,"description":"如何在家中使用 SSH 和 SFTP 协议 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在家中使用 SSH 和 SFTP 协议 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在家中使用 SSH 和 SFTP 协议 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181002 How use SSH and SFTP protocols on your home network","title":"如何在家中使用 SSH 和 SFTP 协议","tag":"201810"},"relativePath":"201810/20181002 How use SSH and SFTP protocols on your home network.md","filePath":"[post].md"}'),u={name:"201810/20181002 How use SSH and SFTP protocols on your home network.md"};function g(S,e,m,h,T,f){const t=i("Link");return d(),l("div",null,[e[20]||(e[20]=r('<h1 id="如何在家中使用-ssh-和-sftp-协议" tabindex="-1">如何在家中使用 SSH 和 SFTP 协议 <a class="header-anchor" href="#如何在家中使用-ssh-和-sftp-协议" aria-label="Permalink to 如何在家中使用 SSH 和 SFTP 协议">​</a></h1><blockquote><p>通过 SSH 和 SFTP 协议，我们能够访问其他设备，有效而且安全的传输文件等等。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/openwires_fromRHT_520_0612LL.png?itok=PqZi55Ab" alt=""></p><p>几年前，我决定配置另外一台电脑，以便我能在工作时访问它来传输我所需要的文件。要做到这一点，最基本的一步是要求你的网络提供商（ISP）提供一个固定的地址。</p><p>有一个不必要但很重要的步骤，就是保证你的这个可以访问的系统是安全的。在我的这种情况下，我计划只在工作场所访问它，所以我能够限定访问的 IP 地址。即使如此，你依然要尽多的采用安全措施。一旦你建立起来这个系统，全世界的人们马上就能尝试访问你的系统。这是非常令人惊奇及恐慌的。你能通过日志文件来发现这一点。我推测有探测机器人在尽其所能的搜索那些没有安全措施的系统。</p><p>在我设置好系统不久后，我觉得这种访问没什么大用，为此，我将它关闭了以便不再为它操心。尽管如此，只要架设了它，在家庭网络中使用 SSH 和 SFTP 还是有点用的。</p><p>当然，有一个必备条件，这个另外的电脑必须已经开机了，至于电脑是否登录与否无所谓的。你也需要知道其 IP 地址。有两个方法能够知道，一个是通过浏览器访问你的路由器，一般情况下你的地址格式类似于 192.168.1.254 这样。通过一些搜索，很容易找出当前是开机的并且接在 eth0 或者 wifi 上的系统。如何识别你所要找到的电脑可能是个挑战。</p><p>更容易找到这个电脑的方式是，打开 shell，输入 ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ifconfig</span></span></code></pre></div><p>命令会输出一些信息，你所需要的信息在 <code>inet</code> 后面，看起来和 192.168.1.234 类似。当你发现这个后，回到你要访问这台主机的客户端电脑，在命令行中输入 ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh gregp@192.168.1.234</span></span></code></pre></div><p>如果要让上面的命令能够正常执行，<code>gregp</code> 必须是该主机系统中正确的用户名。你会被询问其密码。如果你键入的密码和用户名都是正确的，你将通过 shell 环境连接上了这台电脑。我坦诚，对于 SSH 我并不是经常使用的。我偶尔使用它，我能够运行 <code>dnf</code> 来更新我所常使用电脑之外的其它电脑。通常，我用 SFTP ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sftp grego@192.168.1.234</span></span></code></pre></div><p>我更需要用简单的方法来把一个文件传输到另一个电脑。相对于闪存棒和额外的设备，它更加方便，耗时更少。</p><p>一旦连接建立成功，SFTP 有两个基本的命令，<code>get</code>，从主机接收文件 ；<code>put</code>，向主机发送文件。在连接之前，我经常在客户端移动到我想接收或者传输的文件夹下。在连接之后，你将处于一个顶层目录里，比如 <code>home/gregp</code>。一旦连接成功，你可以像在客户端一样的使用 <code>cd</code>，改变你在主机上的工作路径。你也许需要用 <code>ls</code> 来确认你的位置。</p><p>如果你想改变你的客户端的工作目录。用 <code>lcd</code> 命令（ 即 local change directory 的意思）。同样的，用 <code>lls</code> 来显示客户端工作目录的内容。</p><p>如果主机上没有你想要的目录名，你该怎么办？用 <code>mkdir</code> 在主机上创建一个新的目录。或者你可以将整个目录的文件全拷贝到主机 ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>put -r thisDir/</span></span></code></pre></div><p>这将在主机上创建该目录并复制它的全部文件和子目录到主机上。这种传输是非常快速的，能达到硬件的上限。不像在互联网传输一样遇到网络瓶颈。要查看你能在 SFTP 会话中能够使用的命令列表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>man sftp</span></span></code></pre></div><p>我也能够在我的电脑上的 Windows 虚拟机内用 SFTP，这是配置一个虚拟机而不是一个双系统的另外一个优势。这让我能够在系统的 Linux 部分移入或者移出文件。而我只需要在 Windows 中使用一个客户端就行。</p>',21)),n("p",null,[e[2]||(e[2]=s("你能够使用 SSH 或 SFTP 访问通过网线或者 WIFI 连接到你路由器的任何设备。这里，我使用了一个叫做 ")),o(t,{href:"https://play.google.com/store/apps/details?id=berserker.android.apps.sshdroid"},{default:p(()=>e[0]||(e[0]=[s("SSHDroid")])),_:1}),e[3]||(e[3]=s(" 的应用，能够在被动模式下运行 SSH。换句话来说，你能够用你的电脑访问作为主机的 Android 设备。近来我还发现了另外一个应用，")),o(t,{href:"https://play.google.com/store/apps/details?id=com.arpaplus.adminhands&hl=en_US"},{default:p(()=>e[1]||(e[1]=[s("Admin Hands")])),_:1}),e[4]||(e[4]=s("，不管你的客户端是平板还是手机，都能使用 SSH 或者 SFTP 操作。这个应用对于备份和手机分享照片是极好的。"))]),e[21]||(e[21]=n("hr",null,null,-1)),n("p",null,[e[6]||(e[6]=s("via: ")),o(t,{href:"https://opensource.com/article/18/10/ssh-sftp-home-network"},{default:p(()=>e[5]||(e[5]=[s("https://opensource.com/article/18/10/ssh-sftp-home-network")])),_:1})]),n("p",null,[e[11]||(e[11]=s("作者：")),o(t,{href:"https://opensource.com/users/greg-p"},{default:p(()=>e[7]||(e[7]=[s("Geg Pittman")])),_:1}),e[12]||(e[12]=s(" 选题：")),o(t,{href:"https://github.com/lujun9972"},{default:p(()=>e[8]||(e[8]=[s("lujun9972")])),_:1}),e[13]||(e[13]=s(" 译者：")),o(t,{href:"https://github.com/singledo"},{default:p(()=>e[9]||(e[9]=[s("singledo")])),_:1}),e[14]||(e[14]=s(" 校对：")),o(t,{href:"https://github.com/wxy"},{default:p(()=>e[10]||(e[10]=[s("wxy")])),_:1})]),n("p",null,[e[17]||(e[17]=s("本文由 ")),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>e[15]||(e[15]=[s("LCTT")])),_:1}),e[18]||(e[18]=s(" 原创编译，")),o(t,{href:"https://linux.cn/"},{default:p(()=>e[16]||(e[16]=[s("Linux中国")])),_:1}),e[19]||(e[19]=s(" 荣誉推出"))])])}const P=a(u,[["render",g]]);export{k as __pageData,P as default};
